    def test_operator_in_cells_and_values(self):
        rc, out, _ = run_cli('filter', 't.csv', 'note~>=', files=F)
        self.assertEqual(names(out), ['cy'])        # column 'note', op '~', value '>='
        rc, out, _ = run_cli('filter', 't.csv', 'note~=', files=F)
        self.assertEqual(names(out), ['Al', 'cy'])

    def test_exact_numbers(self):
        f = {'n.csv': 'v\n0.1000000000000000000000000000001\n0.1\n12345678901234567890123456789.5\n'}
        rc, out, _ = run_cli('--format', 'csv', 'filter', 'n.csv', 'v>0.1', files=f)
        self.assertEqual(out.splitlines()[1:], ['0.1000000000000000000000000000001', '12345678901234567890123456789.5'])
        rc, out, _ = run_cli('--format', 'csv', 'filter', 'n.csv', 'v==0.10', files=f)
        self.assertEqual(out.splitlines()[1:], ['0.1'])

    def test_file_order_and_formats(self):
        rc, out, _ = run_cli('filter', 't.csv', 'price<=9', '--format=csv', files=F)
        self.assertEqual((rc, out), (0, 'name,price,note\nAl,9,a=b\nal,1.0,\ncy,-2,x>=y\n'))
        rc, out, _ = run_cli('--keep', 'last', '--format', 'json', 'filter', '--kind=left', 't.csv', 'name==cy', files=F)
        self.assertEqual((rc, out.strip()), (0, '[{"name": "cy", "price": "-2", "note": "x>=y"}]'))

    def test_no_rows_keeps_header(self):
        for fmt, want in [('text', 'a  b\n'), ('csv', 'a,b\n'), ('json', '[]\n')]:
            with self.subTest(fmt):
                rc, out, _ = run_cli('--format', fmt, 'filter', 'e.csv', 'a==1', files=F)
                self.assertEqual((rc, out), (0, want))
        rc, out, _ = run_cli('--format', 'csv', 'filter', 't.csv', 'name==zz', files=F)
        self.assertEqual((rc, out), (0, 'name,price,note\n'))

    def test_usage_errors(self):
        for argv in [('filter',), ('filter', 't.csv'), ('filter', 't.csv', 'price'), ('filter', 't.csv', '=5'),
                     ('filter', 't.csv', '==5'), ('filter', 't.csv', '~x'), ('filter', 't.csv', 'price>1', 'oops'),
                     ('filter', 'nofile.csv', 'price'), ('filter', 't.csv', 'price>1', '')]:
            with self.subTest(argv):
                rc, out, err = run_cli(*argv, files=F)
                self.assertEqual((rc, out), (2, ''))
                self.assertTrue(err.startswith('tabula: '))
        self.assertRaises(UsageError, engine.cmd_filter, ['t.csv'], {})

    def test_mistakes_exit_1(self):
        for argv, text in [(('filter', 't.csv', 'cost>1'), "'cost'"), (('filter', 't.csv', 'price>1', 'zip~a'), "'zip'"),
                           (('filter', 'missing.csv', 'a==1'), 'missing.csv')]:
            with self.subTest(argv):
                rc, out, err = run_cli(*argv, files=F)
                self.assertEqual((rc, out), (1, ''))
                self.assertTrue(err.startswith('tabula: ') and text in err)

    def test_registered(self):
        self.assertIn('filter', engine.COMMANDS)
        self.assertIs(engine.COMMANDS['filter'][0], engine.cmd_filter)


if __name__ == '__main__':
    unittest.main()
